mapper.select:
SELECT 
FROM facility f
LEFT JOIN facility_category fc ON f.category_id = fc.category_id
WHERE f.status = 1
  AND f.longitude BETWEEN #{minLng} AND #{maxLng}
  AND f.latitude BETWEEN #{minLat} AND #{maxLat}

sql.where:

    f.facility_name LIKE '%' + #{keyword} + '%'


    AND f.category_id = #{categoryId}


    AND f.district_id = #{districtId}


    AND f.avg_score >= #{minScore}

AND f.status = 1
